package org.deeptimeline.app
const val ICS_TEST_ID="IcsTests_v20261111T042253Z"
fun main(){fun input(vararg body:String):String="BEGIN:VCALENDAR\r\nVERSION:2.0\r\n"+body.joinToString("\r\n")+"\r\nEND:VCALENDAR\r\n"
val source=input("BEGIN:VEVENT","UID:event-1@example.test","SUMMARY:Morning\\, meeting\\; tasks","DTSTART;TZID=America/Denver:20261111T091523","DTEND;TZID=America/Denver:20261111T111523","DURATION:PT2H","END:VEVENT","BEGIN:VEVENT","SUMMARY:Annual\\nReview","DTSTART;VALUE=DATE:20270101","END:VEVENT","BEGIN:VEVENT","SUMMARY:UTC time","DTSTART:20261111T175900Z","RRULE:FREQ=DAILY;COUNT=100","END:VEVENT","BEGIN:VEVENT","SUMMARY:Folded"," DESCRIPTION:irrelevant","DTSTART:20261111T193000","END:VEVENT");val events=IcsImport.parse(source);check(events.size==4);check(events[0].title=="Morning, meeting; tasks");check(events[0].date=="2026-11-11"&&events[0].time=="09:15:23"&&events[0].mode=="LOCAL"&&events[0].zone=="America/Denver");check(events[0].id.isNotBlank());check(events[1].title=="Annual\nReview"&&events[1].time=="00:00:00");check(events[2].mode=="UTC"&&events[2].time=="17:59:00"&&events[2].note.contains("initial"));check(events[3].mode=="LOCAL"&&events[3].zone.isEmpty());check(IcsImport.parse(source)[0].id==events[0].id);val invalid=IcsImport.parse(input("BEGIN:VEVENT","SUMMARY:Absent","END:VEVENT","BEGIN:VEVENT","SUMMARY:Bad zone conflict","DTSTART;TZID=America/Denver:20261111T090000Z","END:VEVENT"));check(invalid.size==2&&invalid[0].error.contains("Missing")&&invalid[1].error.contains("TZID"));val folded=IcsImport.parse(input("BEGIN:VEVENT","SUMMARY:Long name"," continues here","DTSTART:20261111T093012.123456789Z","END:VEVENT"))[0];check(folded.title=="Long namecontinues here"&&folded.time=="09:30:12.123456789");val cancelled=IcsImport.parse(input("BEGIN:VEVENT","SUMMARY:Cancelled","DTSTART:20261111T110000Z","STATUS:CANCELLED","END:VEVENT"))[0];check(cancelled.error=="Cancelled VEVENT");check(runCatching{IcsImport.parse("BEGIN:VEVENT\nDTSTART:20261111T000000Z\nEND:VEVENT")}.isFailure);println("PASS: $ICS_TEST_ID")}
